SPECIAL={
"قورمه‌سبزی":["پیاز و گوشت را تفت بده تا رنگ گوشت عوض شود.","سبزی قورمه را جدا تفت بده و همراه لوبیای خیس‌خورده اضافه کن.","آب جوش و لیموعمانی را اضافه کن و با حرارت ملایم تا جاافتادن بپز.","نمک و ترشی را در پایان تنظیم کن و با برنج سرو کن."],
"کوکو سبزی":["سبزی کوکو، تخم‌مرغ و ادویه را مخلوط کن.","تابه را گرم و کمی چرب کن و مایه را یکدست بریز.","با حرارت ملایم بپز و طرف دوم را هم کامل ببند."],
"زرشک‌پلو با مرغ":["مرغ را با پیاز، ادویه و زعفران تفت بده.","آب اضافه کن و مرغ را آرام بپز.","برنج را جدا آبکش و دم کن.","زرشک را کوتاه گرم کن و همراه زعفران روی برنج بده."],
"جوجه کباب":["مرغ را با پیاز، زعفران، آب‌لیمو و ادویه مزه‌دار کن.","تکه‌ها را سیخ بگیر و گریل یا منقل را گرم کن.","با چرخاندن منظم تا پخت کامل و طلایی‌شدن بپز."]}
FAMILY={
"چلو، پلو و کته":["مواد اصلی را آماده کن.","برنج را متناسب با غذا آبکش یا کته کن.","مواد میانی را آماده و با برنج ترکیب کن.","برنج را دم کن و سرو کن."],
"خورش و قلیه":["پیاز و پایه خورش را تفت بده.","مواد اصلی و چاشنی را اضافه کن.","آب جوش اضافه کن و آرام بپز تا جا بیفتد.","نمک و ترشی را در پایان تنظیم کن."],
"آش، سوپ و حلیم":["مواد دیرپز را اول آماده کن.","پایه مایع را به جوش برسان و مواد را به ترتیب زمان پخت اضافه کن.","آرام بپز تا بافت و مزه یکدست شود.","غلظت و چاشنی را تنظیم کن."],
"کباب، بریان و تنوری":["ماده اصلی را مزه‌دار و کمی استراحت بده.","منقل، گریل یا فر را کاملاً گرم کن.","با حرارت مناسب بپز و در میانه کار برگردان.","پس از پخت کامل چند دقیقه استراحت بده و سرو کن."],
"کوکو و املت":["مواد را آماده و با تخم‌مرغ و ادویه ترکیب کن.","تابه را گرم و کمی چرب کن.","مایه را اضافه کن و با حرارت متوسط تا بسته‌شدن کامل بپز."],
"ماهی و دریایی":["ماهی یا میگو را خشک و مزه‌دار کن.","تابه، گریل یا فر را از قبل گرم کن.","کوتاه و کنترل‌شده بپز تا خشک نشود.","با لیمو و سبزیجات سرو کن."],
"غذای سرد و بدون پخت":["مواد را بشوی، خرد و خنک کن.","به‌آرامی مخلوط کن.","چاشنی را درست قبل از سرو تنظیم کن."]}
DEFAULT=["مواد را آماده و خرد کن.","پایه معطر غذا را آماده کن و مواد اصلی را اضافه کن.","با روش اصلی غذا تا پخت کامل ادامه بده.","چاشنی را تنظیم و سرو کن."]

def recipe_for(food):
    steps=SPECIAL.get(food["name"],FAMILY.get(food.get("family"),DEFAULT))
    methods=food.get("methods") or ["تابه‌ای"]
    return {"steps":steps,"variants":[{"method":m,"primary":i==0} for i,m in enumerate(methods)],"notes":["زمان‌ها تقریبی‌اند و با حجم غذا و قدرت شعله/فر تغییر می‌کنند.","نمک و چاشنی را در پایان دوباره تنظیم کن."]}
